/**
 * Remote File MCP Tools
 *
 * Tools for reading, writing, and managing files in remote Veryfront projects
 * via the REST API. These enable coding agents to edit project files without
 * direct filesystem access.
 *
 * Authentication: Uses the API token from environment or proxy context.
 * API Base: Configurable via VERYFRONT_API_BASE_URL (default: https://api.veryfront.com)
 */
import { defineSchema, lazySchema } from "../../src/schemas/index.js";
import { getEnvironmentConfig } from "../../src/config/index.js";
import { createVeryfrontApiOriginBoundOutboundFetch, guardedExactHttpLoopbackOutboundFetch, guardedOutboundFetch, } from "../../src/security/http/outbound-fetch.js";
import { cwd } from "../../src/platform/index.js";
import { join } from "../../src/platform/compat/path/index.js";
import { withSpan } from "../../src/observability/tracing/otlp-setup.js";
import { randomSuffix } from "../shared/slug.js";
import { DEFAULT_LOCAL_API_URL, resolveRestApiBaseUrl, trimTrailingSlashes, } from "../shared/constants.js";
import { readConfigJsonFile, resolveApiCredentialCandidatesForAuth, resolveApiUrlTrust, } from "../shared/config.js";
import { getEnvSource } from "../../src/utils/env-loader.js";
import { getHostSecret } from "../../src/platform/compat/process/env.js";
import { isHostHttpApiOrigin, requireHostPrivateApiHttps, resolveHostOwnedApiBaseUrl, } from "../../src/config/host-api-base.js";
import { buildProjectApiPath, buildProjectFilePath, getBranchParam, slugToName, } from "./remote-file-tool-helpers.js";
const NativeURL = URL;
const applyIntrinsic = Reflect.apply;
const stringReplace = String.prototype.replace;
const urlPathnameGetter = Object.getOwnPropertyDescriptor(NativeURL.prototype, "pathname")?.get;
const urlHostnameGetter = Object.getOwnPropertyDescriptor(NativeURL.prototype, "hostname")?.get;
const urlProtocolGetter = Object.getOwnPropertyDescriptor(NativeURL.prototype, "protocol")?.get;
const urlHrefGetter = Object.getOwnPropertyDescriptor(NativeURL.prototype, "href")?.get;
function readUrl(url, getter) {
    if (!getter)
        throw new TypeError("Native URL accessor is unavailable");
    return applyIntrinsic(getter, url, []);
}
function validatedEndpoint(candidateApiBaseUrl) {
    const candidate = new NativeURL(candidateApiBaseUrl);
    const addDefaultRestPath = trimTrailingSlashes(readUrl(candidate, urlPathnameGetter)) === "";
    const endpoint = new NativeURL(resolveRestApiBaseUrl(candidateApiBaseUrl, addDefaultRestPath));
    const hostname = readUrl(endpoint, urlHostnameGetter);
    const protocol = readUrl(endpoint, urlProtocolGetter);
    const loopback = hostname === "localhost" || hostname === "127.0.0.1" ||
        hostname === "[::1]" || hostname === "::1";
    if (protocol !== "https:" && !(protocol === "http:" && loopback) &&
        !isHostHttpApiOrigin(readUrl(endpoint, urlHrefGetter))) {
        return {
            ok: false,
            error: "The API endpoint must use HTTPS. HTTP requires a loopback endpoint or an operator-configured API origin.",
            status: 400,
        };
    }
    return endpoint;
}
async function sendApiRequest(endpoint, method, path, token, body) {
    const endpointHref = readUrl(endpoint, urlHrefGetter);
    const normalizedEndpoint = applyIntrinsic(stringReplace, endpointHref, [/\/$/, ""]);
    const url = `${normalizedEndpoint}${path}`;
    try {
        // The credential may be the host-private stored login token, so the
        // request goes through the host transport rather than `globalThis.fetch`.
        // A project served by `veryfront dev` runs in this process and can replace
        // the global, and a direct call would hand its replacement the
        // `Authorization` header to read.
        //
        // Boot-configured HTTP APIs use the exact origin-bound exception.
        // Preserve the explicit-token loopback route for other local endpoints.
        const fetchEndpoint = isHostHttpApiOrigin(endpointHref)
            ? createVeryfrontApiOriginBoundOutboundFetch(endpointHref)
            : readUrl(endpoint, urlProtocolGetter) === "http:"
                ? guardedExactHttpLoopbackOutboundFetch
                : guardedOutboundFetch;
        const response = await fetchEndpoint(url, {
            method,
            headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
            body: body ? JSON.stringify(body) : undefined,
        });
        if (!response.ok) {
            const errorText = await response.text();
            let errorMessage = errorText || `HTTP ${response.status}`;
            try {
                const errorJson = JSON.parse(errorText);
                errorMessage = errorJson.message || errorJson.error || errorMessage;
            }
            catch {
                // Keep the response text when the body is not JSON.
            }
            return { ok: false, error: errorMessage, status: response.status };
        }
        if (response.status === 204)
            return { ok: true, status: 204 };
        return { ok: true, data: (await response.json()), status: response.status };
    }
    catch (error) {
        return {
            ok: false,
            error: error instanceof Error ? error.message : "Network error",
            status: 0,
        };
    }
}
async function apiRequest(method, path, options = {}) {
    const env = getEnvironmentConfig();
    const projectDir = cwd();
    // Remote file tools send to apiBaseUrl, not the higher-precedence apiUrl
    // used by GraphQL/auth calls. Classify the actual destination on its own so
    // a trusted API_URL cannot mask a repository-steered API_BASE_URL.
    const apiBaseSource = getEnvSource("VERYFRONT_API_BASE_URL");
    const requestEnv = apiBaseSource.source === "unset" ? env : { ...env, apiUrl: undefined };
    // Resolve in non-interactive precedence. These tools previously used
    // `env.apiToken` directly, so a project `.env` VERYFRONT_API_TOKEN outranked
    // the stored `veryfront login` token. The interactive ordering reverses that
    // pair, which would silently switch which identity file operations use.
    const candidates = await resolveApiCredentialCandidatesForAuth(requestEnv, projectDir, false);
    const candidate = options.token
        ? candidates.find((entry) => entry.apiToken === options.token)
        : candidates[0];
    if (!candidate) {
        const hostPrivateToken = getHostSecret("VERYFRONT_API_TOKEN");
        if (hostPrivateToken) {
            const hostEndpoint = validatedEndpoint(requireHostPrivateApiHttps(resolveHostOwnedApiBaseUrl()));
            if (!(hostEndpoint instanceof NativeURL))
                return hostEndpoint;
            return await sendApiRequest(hostEndpoint, method, path, hostPrivateToken, options.body);
        }
        const configFile = await readConfigJsonFile(projectDir);
        const trust = resolveApiUrlTrust(requestEnv, configFile, join(projectDir, "veryfront.json"));
        if (trust.repositorySteered) {
            return {
                ok: false,
                error: `The project configures an untrusted API endpoint. Set ${trust.steeringEnvKey ?? "VERYFRONT_API_BASE_URL"} in your shell to confirm the endpoint before using remote file tools.`,
                status: 403,
            };
        }
        return { ok: false, error: "No API token available. Set VERYFRONT_API_TOKEN.", status: 401 };
    }
    const token = candidate.apiToken;
    const candidateApiBaseUrl = candidate.validationEnv.apiBaseUrl || DEFAULT_LOCAL_API_URL;
    let endpoint;
    try {
        endpoint = validatedEndpoint(candidateApiBaseUrl);
    }
    catch {
        return { ok: false, error: "The API endpoint must be a valid URL.", status: 400 };
    }
    if (!(endpoint instanceof NativeURL))
        return endpoint;
    return await sendApiRequest(endpoint, method, path, token, options.body);
}
function remoteFileSize(file) {
    return (file.size_bytes ?? file.size);
}
const MAX_SLUG_ATTEMPTS = 10;
/**
 * Create a project with slug conflict retry.
 * On 409, appends a random suffix and retries (matches reserveProjectSlug behavior).
 * Name is derived from the base slug (without random suffix) for readability.
 */
async function createProjectWithRetry(slug, body) {
    const name = slugToName(slug);
    let currentSlug = slug;
    for (let attempt = 1; attempt <= MAX_SLUG_ATTEMPTS; attempt++) {
        const result = await apiRequest("POST", "/projects", {
            body: { ...body, slug: currentSlug, name },
        });
        if (result.ok && result.data) {
            return { ok: true, data: result.data, slug: currentSlug };
        }
        if (result.status !== 409) {
            return { ok: false, error: result.error ?? "Failed to create project" };
        }
        currentSlug = `${slug}-${randomSuffix()}`;
    }
    return { ok: false, error: `Could not find available slug after ${MAX_SLUG_ATTEMPTS} attempts` };
}
