const getRemoteListFilesInput = defineSchema((v) => v.object({
    project: v.string().describe("Project slug or ID"),
    branch: v.string().optional().describe("Branch name (omit for main branch)"),
    pattern: v.string().optional().describe("File pattern filter (e.g., *.tsx, pages/*)"),
    limit: v.number().optional().default(50).describe("Maximum number of files to return (default: 50)"),
}));
const remoteListFilesInput = lazySchema(getRemoteListFilesInput);
export const vfRemoteListFiles = {
    name: "vf_remote_list_files",
    title: "List Remote Files",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "List files in a remote Veryfront project. Returns file paths, types, sizes, version IDs, and binary metadata. Use this to explore a project's structure.",
    inputSchema: remoteListFilesInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_remote_list_files", async () => {
        const params = new URLSearchParams();
        if (input.pattern)
            params.set("pattern", input.pattern);
        params.set("limit", String(input.limit));
        // The branch file route answers `size` only; the project route answers
        // `size_bytes` beside it.
        params.set("fields", input.branch
            ? "(id,path,type,size,version_id,binary)"
            : "(id,path,type,size_bytes,size,version_id,binary)");
        const apiPath = `${buildProjectApiPath(input.project, "files", input.branch)}?${params.toString()}`;
        const result = await apiRequest("GET", apiPath);
        if (!result.ok)
            return { success: false, error: result.error };
        const files = result.data?.data ?? [];
        return {
            success: true,
            files: files.map((f) => ({
                path: f.path,
                type: f.type,
                size: remoteFileSize(f),
                ...(f.id !== undefined ? { id: f.id } : {}),
                ...(f.version_id !== undefined ? { version_id: f.version_id } : {}),
                ...(f.binary !== undefined ? { binary: f.binary } : {}),
            })),
            total: files.length,
        };
    }, { "tool.project": input.project }),
};
