async function prepareCloneSourceFiles({ project, files, }) {
    const prepared = [];
    for (const file of files) {
        if (file.binary !== undefined && file.binary !== null) {
            return {
                error: `Cannot clone binary file "${file.path}" as text. No destination project was created.`,
            };
        }
        const getResult = await apiRequest("GET", buildProjectFilePath(project, file.path));
        if (!getResult.ok || !getResult.data) {
            return {
                error: `Failed to read ${file.path}. No destination project was created.`,
            };
        }
        if (getResult.data.binary !== undefined && getResult.data.binary !== null) {
            return {
                error: `Cannot clone binary file "${file.path}" as text. No destination project was created.`,
            };
        }
        if (typeof getResult.data.content !== "string") {
            return {
                error: `Invalid text content for ${file.path}. No destination project was created.`,
            };
        }
        prepared.push(getResult.data);
    }
    return { files: prepared };
}
export const vfRemoteCloneProject = {
    name: "vf_remote_clone_project",
    title: "Clone Remote Project",
    annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
    description: "Clone a Veryfront project by creating a new project and copying all files from the source.",
    inputSchema: remoteCloneProjectInput,
    execute: (input) => withSpan("cli.mcp.tool.vf_remote_clone_project", async () => {
        const params = new URLSearchParams();
        params.set("limit", "1000");
        if (input.file_pattern)
            params.set("pattern", input.file_pattern);
        const listResult = await apiRequest("GET", `${buildProjectApiPath(input.source_project, "files")}?${params.toString()}`);
        if (!listResult.ok) {
            return {
                success: false,
                error: `Failed to list source files: ${listResult.error}`,
            };
        }
        const sourceFiles = listResult.data?.data ?? [];
        const prepared = await prepareCloneSourceFiles({
            project: input.source_project,
            files: sourceFiles,
        });
        if (prepared.error !== undefined)
            return { success: false, error: prepared.error };
        const createResult = await createProjectWithRetry(input.target_slug, {});
        if (!createResult.ok) {
            return { success: false, error: `Failed to create project: ${createResult.error}` };
        }
        const newProject = createResult.data;
        if (!newProject)
            return { success: false, error: "Project created but no data returned" };
        let filesCopied = 0;
        const errors = [];
        for (const file of prepared.files) {
            const createFileResult = await apiRequest("PUT", buildProjectFilePath(createResult.slug, file.path), { body: { content: file.content } });
            if (createFileResult.ok) {
                filesCopied++;
            }
            else {
                errors.push(`Failed to create ${file.path}: ${createFileResult.error}`);
            }
        }
        return {
            success: errors.length === 0,
            project: newProject,
            files_copied: filesCopied,
            error: errors.length ? errors.join("; ") : undefined,
        };
    }, { "tool.source_project": input.source_project, "tool.target_slug": input.target_slug }),
};
// ============================================================================
// All Remote File Tools
// ============================================================================
export const remoteFileTools = [
    vfRemoteCreateProject,
    vfRemoteCloneProject,
    vfRemoteListFiles,
    vfRemoteGetFile,
    vfRemoteUpdateFile,
    vfRemoteDeleteFile,
    vfRemoteSearchFiles,
    vfRemoteMoveFile,
    vfRemoteListBranches,
    vfRemoteCreateBranch,
    vfRemoteMergeBranch,
    vfRemoteDeleteBranch,
];
